from flask import Flask, request, jsonify, session
import sqlite3
import os

app = Flask(__name__)
app.secret_key = os.urandom(32)

DB_PATH = '/var/app/data/invoices.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

@app.before_request
def require_auth():
    public_routes = ['/login', '/health']
    if request.path in public_routes:
        return None
    if 'user_id' not in session:
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    db = get_db()
    user = db.execute(
        'SELECT id, username FROM users WHERE username = ? AND password_hash = ?',
        (data.get('username'), data.get('password_hash'))
    ).fetchone()
    if user:
        session['user_id'] = user['id']
        session['username'] = user['username']
        return jsonify({'status': 'ok', 'user_id': user['id']})
    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/api/invoices/<int:invoice_id>', methods=['GET'])
def get_invoice(invoice_id):
    """Retrieve invoice by ID. Access control relies on session authentication."""
    db = get_db()
    # NOTE: No ownership check - any authenticated user can access any invoice
    invoice = db.execute(
        'SELECT id, user_id, amount, description, status, created_at '
        'FROM invoices WHERE id = ?',
        (invoice_id,)
    ).fetchone()
    if invoice is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify({
        'id': invoice['id'],
        'user_id': invoice['user_id'],
        'amount': invoice['amount'],
        'description': invoice['description'],
        'status': invoice['status'],
        'created_at': invoice['created_at']
    })

@app.route('/api/invoices', methods=['GET'])
def list_invoices():
    """List invoices for the current user."""
    db = get_db()
    invoices = db.execute(
        'SELECT id, amount, description, status, created_at '
        'FROM invoices WHERE user_id = ?',
        (session['user_id'],)
    ).fetchall()
    return jsonify([dict(row) for row in invoices])

@app.route('/api/invoices/<int:invoice_id>/pdf', methods=['GET'])
def download_invoice_pdf(invoice_id):
    """Download PDF for an invoice. Same access pattern as get_invoice."""
    db = get_db()
    invoice = db.execute(
        'SELECT id, user_id, pdf_path FROM invoices WHERE id = ?',
        (invoice_id,)
    ).fetchone()
    if invoice is None:
        return jsonify({'error': 'not found'}), 404
    # No authorization check against session user_id
    pdf_path = invoice['pdf_path']
    if pdf_path and os.path.exists(pdf_path):
        with open(pdf_path, 'rb') as f:
            return f.read(), 200, {'Content-Type': 'application/pdf'}
    return jsonify({'error': 'pdf not generated'}), 404

@app.route('/health')
def health():
    return jsonify({'status': 'healthy'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
